import { Component, ViewChild} from '@angular/core';
import { ModalService } from './Shared/services/modal.service';
import { AuthService } from './Shared/services/auth.service';

import { ShareComponent } from './POC-Components/share/share.component';

@Component({
    selector: 'app-root',
    templateUrl: './app.component.html',
    styleUrls: ['./app.component.css']
})
export class AppComponent {
    title = 'app';
    public searchword!: string ;
    public url!: string;
    public type!: string;
    isAuthenticated: boolean = false;
    public userProfile: any;
    public urlEmit!: string;
    public shareLink!: string;
    public showSharePanel: boolean = false;
    public showUploadDataPanel : boolean = false;
    public showFAQ: boolean = false;
    public showChatrooms:boolean = false;

    
    @ViewChild('modal', { read: false })
    modal!: ShareComponent;
    //public clickedEvent: Event;
    constructor(private modalService: ModalService, public auth:AuthService) {
        this.searchword = "video";
        this.type ="video";
        auth.handleAuthentication();
	}
    openModal(id: string) {
        this.modalService.open(id);
    }
	public click() {
     
	}

    childEventClicked(event: any) {
      
        this.searchword = event.searchword ;
        this.type = event.type;
        this.shareLink ="https://talash.azurewebsites.net" +"?type=" + this.type + "&searchword=" + this.searchword;
      
       
    }
    childEventClicked1(event: string) {

       
        this.url = event[2];
       
        console.log("url in parent  :" + this.url);
    }

    ShowShreLink()
    {
        this.shareLink ="https://talash.azurewebsites.net" +"?type=" + this.type + "&searchword=" + this.searchword;
    }
    

    openModal1() {
        this.modal.open();
    }
    ShowHidePanels(value:string)
    {
        if(value == 'upload')
            {
                this.showUploadDataPanel = true;
                this.showSharePanel = false;
                this.showFAQ = false;
                this.showChatrooms = false;
            } 
        if(value == 'share') 
            {
                this.showSharePanel = true;
                this.showUploadDataPanel = false;
                this.showFAQ = false;
                this.showChatrooms = false;
            }
            if(value == 'faq')
            {
                this.showFAQ = true;
                this.showSharePanel = false;
                this.showUploadDataPanel = false;
                this.showChatrooms = false;
            }
            if (value == 'chatrooms')
            {
                this.showChatrooms = true;
                this.showFAQ = false;
                this.showSharePanel = false;
                this.showUploadDataPanel = false;

            }
    }
}
<section class="search-card">
  <div class="search-row">
    <label class="search-label" for="basic-search">Search term</label>
    <input
      id="basic-search"
      class="search-input"
      type="text"
      maxlength="150"
      value="Sydney"
      [(ngModel)]="placeId"
    />
    <button class="btn btn-primary search-button" type="button" (click)="sendNotification(placeId,typeId)">
      Search
    </button>
  </div>

  <div class="type-options" role="radiogroup" aria-label="Content type">
    <label class="type-option">
      <input type="radio" name="type" value="image" [(ngModel)]="typeId" checked />
      <span>image</span>
    </label>
    <label class="type-option">
      <input type="radio" name="type" value="video" [(ngModel)]="typeId" />
      <span>video</span>
    </label>
    <label class="type-option">
      <input type="radio" name="type" value="pdf" [(ngModel)]="typeId" />
      <span>profiles</span>
    </label>
  </div>
</section>

<section class="search-card">
  <div class="search-row">
    <label class="search-label" for="advanced-search">Advanced search by keywords, categories</label>
    <input
      id="advanced-search"
      class="search-input"
      type="text"
      maxlength="150"
      value="education,technology"
      [(ngModel)]="advancedkeywords"
    />
    <button class="btn btn-primary search-button" type="button" (click)="SearchByKeywords()">
      Search
    </button>
  </div>
</section>
